 f.toggleFold(true);matches(f,'open midway');const before=copy(f.s);f.toggleFold(false);const closed=f.fold.totalWrites();f.tick(.4);eq(f.fold.totalWrites(),closed,'fold stays untouched during developing');ok(f.s.develop>before.develop,'physical process continues while diagram folded');f.toggleFold(true);matches(f,'reopen current state');f.finish();
