 ok(source.includes('width:100%;height:auto;max-height:188px;overflow:hidden'),'diagram bounded to its observer width');ok(!/requestAnimationFrame|setInterval|setTimeout|\.animate\(/.test(source.slice(source.indexOf(' function mountPaperPath'),source.indexOf(' const observe='))),'mount has no independent driver');
